CREATE TABLE public.event_rescheduling_campaigns (event_id uuid PRIMARY KEY REFERENCES public.events(id), public_enabled boolean NOT NULL DEFAULT false, policy_version text NOT NULL, proposed_start date NOT NULL, proposed_end date NOT NULL, options jsonb NOT NULL, jersey_price numeric(14,2) NOT NULL DEFAULT 50000 CHECK(jersey_price>=0), consent_text text NOT NULL, policy_text text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.event_rescheduling_campaigns TO authenticated; GRANT ALL ON public.event_rescheduling_campaigns TO service_role;
ALTER TABLE public.event_rescheduling_campaigns ENABLE ROW LEVEL SECURITY;
CREATE POLICY rescheduling_config_admin ON public.event_rescheduling_campaigns FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.is_super_admin(auth.uid()));
CREATE TABLE public.reservation_rescheduling_requests (reservation_id uuid PRIMARY KEY REFERENCES public.event_reservations(id),event_id uuid NOT NULL REFERENCES public.event_rescheduling_campaigns(event_id),choice text NOT NULL,jersey_requested boolean,jersey_size text,delivery text,jersey_consent boolean NOT NULL DEFAULT false,consent_at timestamptz NOT NULL,consent_text text NOT NULL,policy_version text NOT NULL,origin text NOT NULL CHECK(origin IN ('personal_token','owner_session','admin')),source text NOT NULL,note text NOT NULL DEFAULT '',review_status text NOT NULL DEFAULT 'pendiente' CHECK(review_status IN ('pendiente','en_revision','validada','requiere_contacto')),admin_note text NOT NULL DEFAULT '',reviewed_by uuid,reviewed_at timestamptz,actor_id uuid,revision integer NOT NULL DEFAULT 1 CHECK(revision>0),command_id uuid NOT NULL,snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(delivery IS NULL OR delivery IN ('retiro','envio')),CHECK(jersey_requested IS DISTINCT FROM true OR (jersey_consent AND jersey_size IS NOT NULL AND delivery IS NOT NULL)),CHECK(choice IN ('refund','credit') OR (jersey_requested IS NULL AND jersey_size IS NULL AND delivery IS NULL AND NOT jersey_consent)));
GRANT SELECT ON public.reservation_rescheduling_requests TO authenticated; GRANT ALL ON public.reservation_rescheduling_requests TO service_role;
ALTER TABLE public.reservation_rescheduling_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY rescheduling_requests_admin ON public.reservation_rescheduling_requests FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.is_super_admin(auth.uid()));
CREATE TABLE public.reservation_rescheduling_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),reservation_id uuid NOT NULL REFERENCES public.event_reservations(id),revision integer NOT NULL,command_id uuid NOT NULL UNIQUE,actor_id uuid,origin text NOT NULL,before_data jsonb,after_data jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(reservation_id,revision));
GRANT SELECT ON public.reservation_rescheduling_history TO authenticated; GRANT ALL ON public.reservation_rescheduling_history TO service_role;
ALTER TABLE public.reservation_rescheduling_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY rescheduling_history_admin ON public.reservation_rescheduling_history FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.is_super_admin(auth.uid()));
CREATE TABLE public.training_camp_credit_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),source_reservation_id uuid NOT NULL UNIQUE REFERENCES public.event_reservations(id),beneficiary_alumno_id uuid,beneficiary_external_id uuid,currency text NOT NULL DEFAULT 'ARS' CHECK(currency='ARS'),balance numeric(14,2) NOT NULL DEFAULT 0 CHECK(balance>=0),created_at timestamptz NOT NULL DEFAULT now(),CHECK(num_nonnulls(beneficiary_alumno_id,beneficiary_external_id)=1));
GRANT SELECT ON public.training_camp_credit_accounts TO authenticated; GRANT ALL ON public.training_camp_credit_accounts TO service_role;
ALTER TABLE public.training_camp_credit_accounts ENABLE ROW LEVEL SECURITY;
CREATE POLICY camp_credit_admin ON public.training_camp_credit_accounts FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.is_super_admin(auth.uid()));
CREATE TABLE public.training_camp_credit_ledger (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),account_id uuid NOT NULL REFERENCES public.training_camp_credit_accounts(id),kind text NOT NULL CHECK(kind IN ('issue','apply','reverse')),amount numeric(14,2) NOT NULL CHECK(amount>0),target_reservation_id uuid REFERENCES public.event_reservations(id),reverses_id uuid UNIQUE REFERENCES public.training_camp_credit_ledger(id),idempotency_key uuid NOT NULL UNIQUE,actor_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK((kind='reverse')=(reverses_id IS NOT NULL)),CHECK(kind<>'apply' OR target_reservation_id IS NOT NULL));
CREATE UNIQUE INDEX camp_credit_single_issue ON public.training_camp_credit_ledger(account_id) WHERE kind='issue';
GRANT SELECT ON public.training_camp_credit_ledger TO authenticated; GRANT ALL ON public.training_camp_credit_ledger TO service_role;
ALTER TABLE public.training_camp_credit_ledger ENABLE ROW LEVEL SECURITY;
CREATE POLICY camp_ledger_admin ON public.training_camp_credit_ledger FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.is_super_admin(auth.uid()));
CREATE FUNCTION public.rescheduling_finance_locked() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Operaciones financieras bloqueadas: falta integración y conciliación aprobada'; END $$;
CREATE TRIGGER camp_account_locked BEFORE INSERT OR UPDATE OR DELETE ON public.training_camp_credit_accounts FOR EACH ROW EXECUTE FUNCTION public.rescheduling_finance_locked();
CREATE TRIGGER camp_ledger_locked BEFORE INSERT OR UPDATE OR DELETE ON public.training_camp_credit_ledger FOR EACH ROW EXECUTE FUNCTION public.rescheduling_finance_locked();
CREATE FUNCTION public._rescheduling_admin() RETURNS boolean LANGUAGE sql STABLE SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND (public.has_role(auth.uid(),'admin') OR public.is_super_admin(auth.uid())) $$;
REVOKE ALL ON FUNCTION public._rescheduling_admin() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public._rescheduling_admin() TO authenticated,service_role;
CREATE FUNCTION public._rescheduling_financial(p_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE r record;paid numeric;refunds numeric;din numeric;dout numeric;obligation jsonb;ambiguous boolean;transfer boolean; BEGIN
SELECT * INTO r FROM event_reservations WHERE id=p_id;
SELECT coalesce(sum(coalesce(obligation_amount_contract,equivalent_amount_event_currency,amount)),0),coalesce(bool_or(coalesce(event_currency,r.currency_snapshot,r.moneda,'ARS')<>'ARS' OR (currency<>'ARS' AND obligation_amount_contract IS NULL AND equivalent_amount_event_currency IS NULL)),false) INTO paid,ambiguous FROM reservation_payments WHERE reservation_id=p_id AND status='validado' AND anulado_at IS NULL;
SELECT coalesce(sum(monto) FILTER(WHERE moneda='ARS'),0),ambiguous OR coalesce(bool_or(moneda<>'ARS'),false) INTO refunds,ambiguous FROM devoluciones WHERE reservation_id=p_id OR reservation_payment_id IN(SELECT id FROM reservation_payments WHERE reservation_id=p_id);
SELECT coalesce(sum(amount) FILTER(WHERE replacement_reservation_id=p_id),0),coalesce(sum(amount) FILTER(WHERE original_reservation_id=p_id),0),ambiguous OR coalesce(bool_or(currency<>'ARS'),false) INTO din,dout,ambiguous FROM reservation_transfer_direct_payments WHERE (replacement_reservation_id=p_id OR original_reservation_id=p_id) AND status='confirmed' AND voided_at IS NULL;
SELECT EXISTS(SELECT 1 FROM reservation_transfers WHERE (original_reservation_id=p_id OR replacement_reservation_id=p_id) AND status<>'cancelled') INTO transfer;
SELECT jsonb_build_object('status',estado,'suggested',monto_sugerido,'returned',monto_devuelto) INTO obligation FROM reservation_refund_obligations WHERE reservation_id=p_id;
RETURN jsonb_build_object('paid_reybaud',paid,'direct_paid',din,'direct_received',dout,'previous_refunds',refunds,'effective_paid',paid+din,'estimated_remaining',greatest(paid+din-refunds-dout,0),'requires_reconciliation',transfer OR ambiguous OR coalesce(r.currency_snapshot,r.moneda,'ARS')<>'ARS','has_transfer',transfer,'refund_obligation',obligation,'credit_available',0,'credit_used',0,'finance_enabled',false); END $$;
REVOKE ALL ON FUNCTION public._rescheduling_financial(uuid) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public._rescheduling_size(p_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE e uuid;sv jsonb;opts jsonb;answer text;admin_size text; BEGIN
SELECT event_id INTO e FROM event_reservations WHERE id=p_id;
SELECT s INTO sv FROM events,jsonb_array_elements(coalesce(metadata->'choice_surveys','[]')) s WHERE id=e AND s->>'key'='talle_camiseta' AND s->>'enabled'='true';
SELECT coalesce(jsonb_agg(o),'[]') INTO opts FROM jsonb_array_elements(coalesce(sv->'options','[]')) o WHERE coalesce((o->>'needs_follow_up')::boolean,false)=false;
SELECT data->>'respuesta' INTO answer FROM reservation_checklist_data WHERE reservation_id=p_id AND step_key='encuesta_talle_camiseta';
IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(opts) o WHERE o->>'value'=answer) THEN answer:=NULL; END IF;
SELECT confirmed_value INTO admin_size FROM event_choice_survey_admin_entries WHERE reservation_id=p_id AND survey_key='talle_camiseta' AND status='confirmed';
IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(opts) o WHERE o->>'value'=admin_size) THEN admin_size:=NULL; END IF;
RETURN jsonb_build_object('options',opts,'survey',answer,'administration',admin_size,'conflict',answer IS NOT NULL AND admin_size IS NOT NULL AND answer<>admin_size,'confirmed',CASE WHEN answer IS NOT NULL AND admin_size IS NOT NULL AND answer<>admin_size THEN NULL ELSE coalesce(answer,admin_size) END); END $$;
REVOKE ALL ON FUNCTION public._rescheduling_size(uuid) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.get_rescheduling_context(p_event_id uuid,p_reservation_id uuid DEFAULT NULL,p_token text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE c record;r record;arr jsonb:='[]';isadmin boolean:=public._rescheduling_admin();owned boolean; BEGIN
SELECT * INTO c FROM event_rescheduling_campaigns WHERE event_id=p_event_id;
IF NOT FOUND OR (NOT c.public_enabled AND NOT isadmin) THEN RETURN jsonb_build_object('available',false); END IF;
IF NOT isadmin AND p_token IS NULL AND auth.uid() IS NULL THEN RETURN jsonb_build_object('available',true,'auth_required',true); END IF;
FOR r IN SELECT er.*,coalesce(nullif(concat_ws(' ',a.nombre,a.apellido),''),nullif(concat_ws(' ',ep.nombre,ep.apellido),''),concat_ws(' ',er.external_first_name,er.external_last_name)) AS participant FROM event_reservations er LEFT JOIN alumnos a ON a.id=er.alumno_id LEFT JOIN event_external_participants ep ON ep.id=er.external_participant_id WHERE er.event_id=p_event_id AND er.reservation_status NOT IN ('cancelada','rechazada','cancelled','cancelado') AND (p_reservation_id IS NULL OR er.id=p_reservation_id) LOOP
owned:=isadmin OR (p_token IS NOT NULL AND length(p_token)>=20 AND r.access_token=p_token) OR (p_token IS NULL AND auth.uid() IS NOT NULL AND (EXISTS(SELECT 1 FROM alumnos a WHERE a.id=r.alumno_id AND (a.user_id=auth.uid() OR (auth.jwt()->>'email_verified' IS DISTINCT FROM 'false' AND lower(a.email)=lower(auth.email())))) OR (auth.jwt()->>'email_verified' IS DISTINCT FROM 'false' AND (lower(nullif(r.external_email,''))=lower(auth.email()) OR EXISTS(SELECT 1 FROM event_external_participants ep WHERE ep.id=r.external_participant_id AND lower(ep.email)=lower(auth.email()))))));
IF owned THEN arr:=arr || jsonb_build_array(jsonb_build_object('reservation_id',r.id,'participant',r.participant,'package',r.package_nombre_snapshot,'financial',public._rescheduling_financial(r.id),'size',public._rescheduling_size(r.id),'request',(SELECT to_jsonb(q)-'snapshot'-'actor_id'-'reviewed_by'-'command_id' FROM reservation_rescheduling_requests q WHERE q.reservation_id=r.id))); END IF; END LOOP;
RETURN jsonb_build_object('available',true,'admin',isadmin,'campaign',to_jsonb(c),'reservations',arr); END $$;
REVOKE ALL ON FUNCTION public.get_rescheduling_context(uuid,uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.get_rescheduling_context(uuid,uuid,text) TO anon,authenticated;
CREATE FUNCTION public.submit_rescheduling_request(p_event_id uuid,p_reservation_id uuid,p_input jsonb,p_expected_revision integer,p_command_id uuid,p_token text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c record;r record;oldrow reservation_rescheduling_requests%ROWTYPE;newrow reservation_rescheduling_requests%ROWTYPE;ctx jsonb;financial jsonb;sz jsonb;opt jsonb;isadmin boolean:=public._rescheduling_admin();ch text:=p_input->>'choice';j boolean;jc boolean;js text;dl text;src text;nt text; BEGIN
IF p_command_id IS NULL OR p_expected_revision IS NULL OR jsonb_typeof(p_input)<>'object' OR length(p_input::text)>8000 THEN RAISE EXCEPTION 'Solicitud inválida'; END IF;
SELECT * INTO c FROM event_rescheduling_campaigns WHERE event_id=p_event_id FOR SHARE;
IF NOT FOUND OR (NOT c.public_enabled AND NOT isadmin) THEN RAISE EXCEPTION 'Reprogramación aún no habilitada'; END IF;
SELECT * INTO r FROM event_reservations WHERE id=p_reservation_id AND event_id=p_event_id FOR UPDATE;
IF NOT FOUND OR r.reservation_status IN ('cancelada','rechazada','cancelled','cancelado') THEN RAISE EXCEPTION 'Reserva no disponible'; END IF;
ctx:=public.get_rescheduling_context(p_event_id,p_reservation_id,p_token);
IF jsonb_array_length(coalesce(ctx->'reservations','[]'))<>1 THEN RAISE EXCEPTION 'Acceso no autorizado'; END IF;
SELECT * INTO oldrow FROM reservation_rescheduling_requests WHERE reservation_id=p_reservation_id;
IF EXISTS(SELECT 1 FROM reservation_rescheduling_history WHERE command_id=p_command_id) THEN IF EXISTS(SELECT 1 FROM reservation_rescheduling_history WHERE command_id=p_command_id AND reservation_id=p_reservation_id) THEN RETURN to_jsonb(oldrow)-'snapshot'-'actor_id'-'reviewed_by'-'command_id'; END IF; RAISE EXCEPTION 'Identificador ya utilizado'; END IF;
IF coalesce(oldrow.revision,0)<>p_expected_revision THEN RAISE EXCEPTION 'Otra respuesta fue guardada. Recargá antes de continuar'; END IF;
SELECT o INTO opt FROM jsonb_array_elements(c.options) o WHERE o->>'value'=ch;
IF opt IS NULL OR coalesce((p_input->>'consent')::boolean,false)=false THEN RAISE EXCEPTION 'Elegí una opción y confirmá el consentimiento'; END IF;
src:=CASE WHEN isadmin THEN nullif(trim(p_input->>'source'),'') ELSE CASE WHEN p_token IS NULL THEN 'Sesión verificada' ELSE 'Enlace personal' END END;nt:=coalesce(p_input->>'note','');
IF isadmin AND (src IS NULL OR length(src)>120 OR length(trim(nt))=0) THEN RAISE EXCEPTION 'Fuente y nota administrativa obligatorias'; END IF; IF length(nt)>2000 THEN RAISE EXCEPTION 'Nota demasiado extensa'; END IF;
financial:=public._rescheduling_financial(p_reservation_id);sz:=public._rescheduling_size(p_reservation_id);
IF ch IN ('refund','credit') THEN j:=(p_input->>'jersey_requested')::boolean; IF j THEN jc:=coalesce((p_input->>'jersey_consent')::boolean,false);js:=p_input->>'jersey_size';dl:=p_input->>'delivery'; IF NOT jc OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(sz->'options') o WHERE o->>'value'=js) OR dl IS NULL OR dl NOT IN ('retiro','envio') THEN RAISE EXCEPTION 'Confirmá talle, entrega y consentimiento del jersey'; END IF; IF NOT (financial->>'requires_reconciliation')::boolean AND (financial->>'estimated_remaining')::numeric<c.jersey_price THEN RAISE EXCEPTION 'Saldo insuficiente para solicitar deducción del jersey'; END IF; END IF; END IF;
INSERT INTO reservation_rescheduling_requests(reservation_id,event_id,choice,jersey_requested,jersey_size,delivery,jersey_consent,consent_at,consent_text,policy_version,origin,source,note,actor_id,revision,command_id,snapshot) VALUES(p_reservation_id,p_event_id,ch,j,js,dl,coalesce(jc,false),now(),c.consent_text,c.policy_version,CASE WHEN isadmin THEN 'admin' WHEN p_token IS NULL THEN 'owner_session' ELSE 'personal_token' END,src,nt,auth.uid(),coalesce(oldrow.revision,0)+1,p_command_id,jsonb_build_object('financial',financial,'size',sz,'option',opt,'policy',c.policy_text,'jersey_price',c.jersey_price,'historical_date',(SELECT date FROM events WHERE id=p_event_id),'historical_end_date',(SELECT end_date FROM events WHERE id=p_event_id),'package_id',r.package_id,'reservation_status',r.reservation_status,'terms_version',r.terminos_version_aceptada)) ON CONFLICT(reservation_id) DO UPDATE SET choice=excluded.choice,jersey_requested=excluded.jersey_requested,jersey_size=excluded.jersey_size,delivery=excluded.delivery,jersey_consent=excluded.jersey_consent,consent_at=excluded.consent_at,consent_text=excluded.consent_text,policy_version=excluded.policy_version,origin=excluded.origin,source=excluded.source,note=excluded.note,actor_id=excluded.actor_id,revision=excluded.revision,command_id=excluded.command_id,snapshot=excluded.snapshot,review_status='pendiente',admin_note='',reviewed_by=NULL,reviewed_at=NULL,updated_at=now() RETURNING * INTO newrow;
INSERT INTO reservation_rescheduling_history(reservation_id,revision,command_id,actor_id,origin,before_data,after_data) VALUES(p_reservation_id,newrow.revision,p_command_id,auth.uid(),newrow.origin,CASE WHEN oldrow.reservation_id IS NULL THEN NULL ELSE to_jsonb(oldrow) END,to_jsonb(newrow));
RETURN to_jsonb(newrow)-'snapshot'-'actor_id'-'reviewed_by'-'command_id'; END $$;
REVOKE ALL ON FUNCTION public.submit_rescheduling_request(uuid,uuid,jsonb,integer,uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.submit_rescheduling_request(uuid,uuid,jsonb,integer,uuid,text) TO anon,authenticated;
CREATE FUNCTION public.admin_review_rescheduling(p_reservation_id uuid,p_revision integer,p_status text,p_note text,p_command_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE oldrow reservation_rescheduling_requests%ROWTYPE;newrow reservation_rescheduling_requests%ROWTYPE; BEGIN
IF NOT public._rescheduling_admin() THEN RAISE EXCEPTION 'Acceso no autorizado'; END IF;
IF p_status IS NULL OR p_status NOT IN ('pendiente','en_revision','validada','requiere_contacto') OR length(trim(coalesce(p_note,'')))=0 OR length(p_note)>2000 OR p_command_id IS NULL THEN RAISE EXCEPTION 'Estado y nota obligatorios'; END IF;
SELECT * INTO oldrow FROM reservation_rescheduling_requests WHERE reservation_id=p_reservation_id FOR UPDATE;
IF EXISTS(SELECT 1 FROM reservation_rescheduling_history WHERE command_id=p_command_id AND reservation_id=p_reservation_id) THEN RETURN; END IF;
IF oldrow.reservation_id IS NULL OR oldrow.revision<>p_revision THEN RAISE EXCEPTION 'La respuesta cambió. Recargá'; END IF;
UPDATE reservation_rescheduling_requests SET review_status=p_status,admin_note=p_note,reviewed_by=auth.uid(),reviewed_at=now(),updated_at=now(),revision=revision+1,command_id=p_command_id WHERE reservation_id=p_reservation_id RETURNING * INTO newrow;
INSERT INTO reservation_rescheduling_history(reservation_id,revision,command_id,actor_id,origin,before_data,after_data) VALUES(p_reservation_id,newrow.revision,p_command_id,auth.uid(),'admin',to_jsonb(oldrow),to_jsonb(newrow)); END $$;
REVOKE ALL ON FUNCTION public.admin_review_rescheduling(uuid,integer,text,text,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_review_rescheduling(uuid,integer,text,text,uuid) TO authenticated;
CREATE FUNCTION public.admin_rescheduling_report(p_event_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE ctx jsonb;prior jsonb; BEGIN IF NOT public._rescheduling_admin() THEN RAISE EXCEPTION 'Acceso no autorizado'; END IF;ctx:=public.get_rescheduling_context(p_event_id); SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'status',status,'original_reservation_id',original_reservation_id,'replacement_reservation_id',replacement_reservation_id,'package_id',package_id)),'[]') INTO prior FROM reservation_transfers WHERE event_id=p_event_id; RETURN ctx || jsonb_build_object('transfers',prior); END $$;
REVOKE ALL ON FUNCTION public.admin_rescheduling_report(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_rescheduling_report(uuid) TO authenticated;